import{_ as o,a0 as r,w as f,s as u,ao as s,I as a,x as e,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const U=JSON.parse('{"title":"修復 Ubuntu 中的 “Pending Update of Firefox snap” 錯誤 | LCTT x X-CMD","titleTemplate":false,"description":"修復 Ubuntu 中的 “Pending Update of Firefox snap” 錯誤 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"修復 Ubuntu 中的 “Pending Update of Firefox snap” 錯誤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"修復 Ubuntu 中的 “Pending Update of Firefox snap” 錯誤 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220722 Fixing the -Pending Update of Firefox snap- Error in Ubuntu","title":"修復 Ubuntu 中的 “Pending Update of Firefox snap” 錯誤","tag":"202208","desc":""},"relativePath":"202208/20220722 Fixing the -Pending Update of Firefox snap- Error in Ubuntu.md","filePath":"[post].md"}'),d={name:"202208/20220722 Fixing the -Pending Update of Firefox snap- Error in Ubuntu.md"};function l(x,t,g,b,m,h){const n=r("Link");return f(),u("div",null,[t[21]||(t[21]=s('<h1 id="修復-ubuntu-中的-pending-update-of-firefox-snap-錯誤" tabindex="-1">修復 Ubuntu 中的 “Pending Update of Firefox snap” 錯誤 <a class="header-anchor" href="#修復-ubuntu-中的-pending-update-of-firefox-snap-錯誤" aria-label="Permalink to “修復 Ubuntu 中的 “Pending Update of Firefox snap” 錯誤”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202208/08/154842wquoflgffwyyn2cw.jpg" alt=""></p><p>如果你使用的是 Ubuntu 22.04，你可能已收到過此通知。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/pending-update-firefox-ubuntu.png" alt="Notification about pending Firefox app"></p><p>它會通知你 Firefox 更新正在等待中，並要求你關閉應用以避免中斷。</p><p>因此，就像一個聽話的 Ubuntu 用户一樣，你在保存或完成工作後關閉了 Firefox 瀏覽器。</p><p>你認為 Firefox 已在後台更新，重啓瀏覽器將運行較新版本。</p><p>只是，並非如此。</p><p><strong>即使在你重啓瀏覽器甚至計算機後，它仍可能顯示相同的 “pending update of Firefox” 通知</strong>。</p><p>令人沮喪麼？我可以告訴你發生了什麼。</p><p>讓我解釋一下為什麼會發生這種情況，以及你可以做些什麼來“修復”它。</p><h3 id="修復-pending-update-of-firefox-snap-問題" tabindex="-1">修復 “pending update of Firefox snap” 問題 <a class="header-anchor" href="#修復-pending-update-of-firefox-snap-問題" aria-label="Permalink to “修復 “pending update of Firefox snap” 問題”">​</a></h3>',12)),a("p",null,[t[1]||(t[1]=e("早些時候，Firefox 曾經在後台更新，然後要求你重啓瀏覽器。在你重啓瀏覽器之前 ",-1)),i(n,{href:"https://news.itsfoss.com/mozilla-annoying-new-tab/"},{default:p(()=>[...t[0]||(t[0]=[e("不能",-1)])]),_:1}),t[2]||(t[2]=e(" 打開任何網站。",-1))]),t[22]||(t[22]=a("p",null,[a("img",{src:"https://itsfoss.com/wp-content/uploads/2022/07/firefox-restart.webp",alt:"Firefox forced restart in the past"})],-1)),a("p",null,[t[4]||(t[4]=e("在將 ",-1)),i(n,{href:"https://news.itsfoss.com/ubuntu-firefox-snap-default/"},{default:p(()=>[...t[3]||(t[3]=[e("Firefox 瀏覽器切換為默認 Snap 包格式",-1)])]),_:1}),t[5]||(t[5]=e(" 後，Ubuntu 團隊對更新流程進行了一些改動。",-1))]),t[23]||(t[23]=s('<p>此通知是“改進的用户體驗”的一部分。現在，Firefox 不再阻止你瀏覽。你可以在方便時重新啓動瀏覽器以進行更新。</p><p>但是為什麼即使在你重新啓動瀏覽器或系統後它仍然顯示這個通知？</p><p>因為這是一條糟糕的通知消息，無法為你提供完整的信息。</p><h4 id="firefox-更新還沒有開始" tabindex="-1">Firefox 更新還沒有開始 <a class="header-anchor" href="#firefox-更新還沒有開始" aria-label="Permalink to “Firefox 更新還沒有開始”">​</a></h4><p>當你看到 “pending Firefox update” 時，你錯誤地認為應用已在後台更新，重啓會將其升級到較新的版本。</p><p>而對於現在這種情況，Ubuntu 中的 Snap 包每天會自動刷新（更新）一次或幾次。為了避免在重新啓動安裝更新之前 Firefox 不允許你瀏覽任何內容而導致工作中斷，Ubuntu 甚至不會在後台更新 Firefox Snap 包。</p><p>相反，當 Snap 包刷新時，<strong>它會顯示通知並希望你立即關閉瀏覽器</strong>，以便可以使用其他 Snap 包進行更新。</p><p>但像你我這樣的用户不能這樣做，對吧？看到通知，立即關閉瀏覽器？並不是很方便。</p><p>而當你有時間關閉瀏覽器時，Snap 刷新卻不會馬上更新瀏覽器。</p><p>你可以看到更新的 Snap 版本的 Firefox 可用，但只要 Firefox 正在運行，它就不會自動安裝。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/pending-Firefox-update-issue-Ubuntu.png" alt="Firefox snap won’t be updated automatically if the browser is running"></p><h4 id="更新-firefox-snap" tabindex="-1">更新 Firefox Snap <a class="header-anchor" href="#更新-firefox-snap" aria-label="Permalink to “更新 Firefox Snap”">​</a></h4><p>這是你擺脱每天不斷出現的更新通知所需要做的事情。</p><ul><li>關閉 Firefox 瀏覽器</li><li>手動運行 Snap 刷新（更新已安裝的 Snap 包）</li></ul><p>確保你在 Firefox 瀏覽器中的工作已保存。現在，使用鼠標關閉所有 Firefox 瀏覽器或在終端中運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo killall firefox</span></span></code></pre></div><p>現在 Firefox 不再運行，更新 Snap 軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo snap refresh</span></span></code></pre></div><p>你會看到它開始下載更新的 Firefox 包。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/updating-firefox-snap-package-ubuntu.png" alt="Firefox is being updated with Snap"></p><p>更新完成後，你將看到 Firefox 已升級到更新版本的摘要信息。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/firefox-snap-update-ubuntu.png" alt="Updated Firefox snap version"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>安裝非 Snap 版本的 Firefox 也可能是個解決方案，但不是每個人都可以走這條路。</p><p>Firefox 和 Snap 的開發人員必須齊心協力改進這個模稜兩可的更新過程。他們應該提供更好的機制，不僅顯示待處理更新的通知，還提供啓動更新的選項。</p><p>這是我們最近在 Ubuntu 上看到的許多奇怪的事情之一。這必須改變才能使 Ubuntu （再次）成為一個對初學者友好的發行版。</p><hr>',27)),a("p",null,[t[7]||(t[7]=e("via: ",-1)),i(n,{href:"https://itsfoss.com/pending-update-firefox-ubuntu/"},{default:p(()=>[...t[6]||(t[6]=[e("https://itsfoss.com/pending-update-firefox-ubuntu/",-1)])]),_:1})]),a("p",null,[t[12]||(t[12]=e("作者：",-1)),i(n,{href:"https://itsfoss.com/"},{default:p(()=>[...t[8]||(t[8]=[e("Abhishek Prakash",-1)])]),_:1}),t[13]||(t[13]=e(" 選題：",-1)),i(n,{href:"https://github.com/lkxed"},{default:p(()=>[...t[9]||(t[9]=[e("lkxed",-1)])]),_:1}),t[14]||(t[14]=e(" 譯者：",-1)),i(n,{href:"https://github.com/geekpi"},{default:p(()=>[...t[10]||(t[10]=[e("geekpi",-1)])]),_:1}),t[15]||(t[15]=e(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:p(()=>[...t[11]||(t[11]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[18]||(t[18]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[16]||(t[16]=[e("LCTT",-1)])]),_:1}),t[19]||(t[19]=e(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:p(()=>[...t[17]||(t[17]=[e("Linux中國",-1)])]),_:1}),t[20]||(t[20]=e(" 榮譽推出",-1))])])}const T=o(d,[["render",l]]);export{U as __pageData,T as default};
